1999	int volc_e2e_hybrid_route_e2e(void)
2000	{
2001	    if (s_hybrid != E2E_HYBRID_PENDING) {
2002	        syslog(LOG_WARNING,
2003	            "[%s] route_e2e: not in PENDING (hybrid=%d turn=%d)\n",
2004	            TAG, (int)s_hybrid, (int)s_turn);
2005	        return -EAGAIN;
2006	    }
2007	
2008	    /* Transition to E2E fast path:
2009	     *   - Set s_hybrid = E2E so volc_e2e_tts knows to drain the ring
2010	     *   - Keep s_pcm_abort = false so pop_pcm can read the ring
2011	     *   - Keep s_pcm_eos as set by TTSEnded (pop_pcm uses it to
2012	     *     return is_last=1 after draining)
2013	     *   - Advance s_turn to TTS_STREAMING so pop_pcm's accept gate
2014	     *     (already open in ASR_DONE) remains open */
2015	    s_hybrid = E2E_HYBRID_E2E;
2016	    s_turn = E2E_TURN_TTS_STREAMING;
2017	
2018	    size_t buffered = ring_count(&s_pcm_ring);
2019	    syslog(LOG_INFO,
2020	        "[%s] hybrid_route=e2e (buffered %zu bytes, eos=%d)\n",
2021	        TAG, buffered, (int)s_pcm_eos);
2022	
2023	    /* If no audio at all (server silent), mark abort so consumer
2024	     * does not block on pop_pcm waiting for data that will never
2025	     * arrive.  The reply will fall back to the error path. */
2026	    if (buffered == 0 && s_pcm_eos) {
2027	        syslog(LOG_WARNING,
2028	            "[%s] hybrid_route=e2e: no server audio available\n", TAG);
2029	        return 0;  /* Caller will pop_pcm and get is_last=1 immediately */
2030	    }
2031	    return 0;
2032	}
