2034	char* volc_e2e_hybrid_route_agent(void)
2035	{
2036	    if (s_hybrid != E2E_HYBRID_PENDING) {
2037	        syslog(LOG_WARNING,
2038	            "[%s] route_agent: not in PENDING (hybrid=%d turn=%d)\n",
2039	            TAG, (int)s_hybrid, (int)s_turn);
2040	        return NULL;
2041	    }
2042	
2043	    /* Grab the server's cached reply BEFORE clearing state (the
2044	     * mutex is needed because recv_thread may still be appending
2045	     * from a late ChatResponse). */
2046	    char* reply = NULL;
2047	    pthread_mutex_lock(&s_reply_lock);
2048	    if (s_server_reply[0]) {
2049	        reply = strdup(s_server_reply);
2050	    }
2051	    pthread_mutex_unlock(&s_reply_lock);
2052	
2053	    /* Discard the buffered server audio: the agent path will
2054	     * synthesize the agent's own text via volc_tts_ws. */
2055	    ring_clear(&s_pcm_ring);
2056	    s_pcm_eos = true;
2057	    s_pcm_abort = true;
2058	
2059	    /* Claim and immediately close the TTS channel so the server stops
2060	     * its self-chat NOW (only when it is still self-chatting).  Without
2061	     * this the server keeps streaming audio we discard, and its late
2062	     * frames / a confused turn state break the next turn (uplink ring
2063	     * fills, server closes the connection). */
2064	    if (s_turn < E2E_TURN_TTS_CLAIMED) {
2065	        volc_e2e_tts_begin();
2066	        volc_e2e_tts_end();
2067	    }
2068	
2069	    /* Advance s_turn so late TTSEnded frames are categorized as
2070	     * "late" and ignored by the state machine. */
2071	    s_turn = E2E_TURN_DONE;
2072	    s_hybrid = E2E_HYBRID_AGENT;
2073	
2074	    syslog(LOG_INFO,
2075	        "[%s] hybrid_route=agent (reply_cached=%d)\n",
2076	        TAG, reply != NULL);
2077	    return reply;
2078	}
