128	        if (!tmp)
129	            return ERROR;
130	        rb->data = tmp;
131	        rb->cap = new_cap;
132	    }
133	    memcpy(rb->data + rb->len, data, len);
134	    rb->len += len;
135	    rb->data[rb->len] = '\0';
136	    return OK;
137	}
