682	static int ws_send_masked(e2e_tls_t* ctx, unsigned char opcode,
683	    const unsigned char* payload, size_t plen)
684	{
685	    if (!ctx || ctx->net.fd < 0) return -EINVAL;
686	
687	    unsigned char hdr[14];
688	    size_t hdr_len = 0;
689	
690	    hdr[0] = WS_FIN_BIT | opcode;
691	
692	    if (plen < 126) {
693	        hdr[1] = WS_MASK_BIT | (unsigned char)plen;
694	        hdr_len = 2;
695	    } else if (plen <= 0xFFFF) {
696	        hdr[1] = WS_MASK_BIT | 126;
697	        hdr[2] = (unsigned char)(plen >> 8);
698	        hdr[3] = (unsigned char)(plen & 0xFF);
699	        hdr_len = 4;
700	    } else {
701	        hdr[1] = WS_MASK_BIT | 127;
702	        memset(hdr + 2, 0, 4);
703	        hdr[6] = (unsigned char)((plen >> 24) & 0xFF);
704	        hdr[7] = (unsigned char)((plen >> 16) & 0xFF);
705	        hdr[8] = (unsigned char)((plen >> 8) & 0xFF);
706	        hdr[9] = (unsigned char)(plen & 0xFF);
707	        hdr_len = 10;
708	    }
709	
710	    unsigned char mask[WS_MASK_KEY_LEN];
711	    entropy_func(NULL, mask, WS_MASK_KEY_LEN);
712	    memcpy(hdr + hdr_len, mask, WS_MASK_KEY_LEN);
713	    hdr_len += WS_MASK_KEY_LEN;
714	
715	    int ret = tls_write_all(ctx, hdr, hdr_len);
716	    if (ret != 0) return ret;
717	
718	    unsigned char chunk[512];
719	    size_t sent = 0;
720	    while (sent < plen) {
721	        size_t clen = plen - sent;
722	        if (clen > sizeof(chunk)) clen = sizeof(chunk);
723	        for (size_t i = 0; i < clen; i++) {
724	            chunk[i] = payload[sent + i] ^ mask[(sent + i) % 4];
725	        }
726	        ret = tls_write_all(ctx, chunk, clen);
727	        if (ret != 0) return ret;
728	        sent += clen;
729	    }
730	    return 0;
731	}
